package com.skyrpg.skyblock.bazaar;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.skyrpg.items.ItemRegistry;
import com.skyrpg.skyblock.SkyRpgSkyblock;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.resources.Identifier;

/**
 * What the Bazaar trades, from {@code data/skyrpg_skyblock/skyrpg/bazaar/catalog.json} (generated by
 * {@code tools/skyblock/import_bazaar.py}): Hypixel's tabs, the groups in each, the products in each group, and what
 * each product cost on Hypixel when the snapshot was taken. Those prices are the market maker's: it sells at
 * {@code buy} and buys at {@code sell} whenever no player's order beats it, so a small server's Bazaar always trades.
 */
public final class BazaarCatalog {
    public record Product(String id, double buy, double sell) {
        static final StreamCodec<RegistryFriendlyByteBuf, Product> CODEC = StreamCodec.composite(
                ByteBufCodecs.STRING_UTF8, Product::id, ByteBufCodecs.DOUBLE, Product::buy, ByteBufCodecs.DOUBLE, Product::sell, Product::new);
    }

    public record Group(String name, String icon, List<Product> products) {
        static final StreamCodec<RegistryFriendlyByteBuf, Group> CODEC = StreamCodec.composite(
                ByteBufCodecs.STRING_UTF8, Group::name, ByteBufCodecs.STRING_UTF8, Group::icon,
                Product.CODEC.apply(ByteBufCodecs.list()), Group::products, Group::new);
    }

    public record Category(String name, List<Group> groups) {
        public static final StreamCodec<RegistryFriendlyByteBuf, Category> CODEC = StreamCodec.composite(
                ByteBufCodecs.STRING_UTF8, Category::name, Group.CODEC.apply(ByteBufCodecs.list()), Category::groups, Category::new);
    }

    private static List<Category> categories = List.of();
    private static Map<String, Product> products = Map.of();

    private BazaarCatalog() {
    }

    static void load(Map<Identifier, JsonElement> files) {
        List<Category> loaded = new ArrayList<>();
        Map<String, Product> byId = new LinkedHashMap<>();
        files.values().forEach(element -> {
            for (JsonElement categoryJson : element.getAsJsonObject().getAsJsonArray("categories")) {
                JsonObject category = categoryJson.getAsJsonObject();
                List<Group> groups = new ArrayList<>();
                for (JsonElement groupJson : category.getAsJsonArray("groups")) {
                    JsonObject group = groupJson.getAsJsonObject();
                    List<Product> list = new ArrayList<>();
                    for (JsonElement productJson : group.getAsJsonArray("products")) {
                        JsonObject product = productJson.getAsJsonObject();
                        Product p = new Product(product.get("id").getAsString(), product.get("buy").getAsDouble(), product.get("sell").getAsDouble());
                        list.add(p);
                        byId.put(p.id(), p);
                    }
                    groups.add(new Group(group.get("name").getAsString(), group.get("icon").getAsString(), List.copyOf(list)));
                }
                loaded.add(new Category(category.get("name").getAsString(), List.copyOf(groups)));
            }
        });
        categories = List.copyOf(loaded);
        products = byId;
        SkyRpgSkyblock.LOGGER.info("Loaded the Bazaar: {} products", byId.size());
    }

    /** Replaces the catalogue with what the server sent (client side). */
    public static void replace(List<Category> sent) {
        categories = List.copyOf(sent);
        Map<String, Product> byId = new LinkedHashMap<>();
        sent.forEach(category -> category.groups().forEach(group -> group.products().forEach(product -> byId.put(product.id(), product))));
        products = byId;
    }

    public static List<Category> categories() {
        return categories;
    }

    /** The product, or null if the Bazaar doesn't trade it (or the item isn't in the game). */
    public static Product product(String id) {
        Product product = products.get(id);
        return product != null && ItemRegistry.skyblock(id) != null ? product : null;
    }
}
